LESSONS = [
 dict(id='B02', title='Blender静态资产：先会验收，再谈从零造型', prereq=['A08','B01'], concepts='KN02/KN11/KN26', goal='为一件静态道具做尺寸、轮廓、原点和法线检查。',
 m=['区分对象变换与网格编辑，判断修正应该发生在哪里。','分清平滑着色与真实倒角，检查游戏距离的轮廓。'], k=['拓扑、面数、修改器是按需求使用的工具；复杂雕刻暂不学。'], stop='不要求手工搭完整人物，不刷所有快捷键，不用建模速度评分。',
 body=['Object Mode改变对象在场景里的变换；Edit Mode修改对象内部几何，可能改变可见形状与原点的关系。静态道具也要留原文件，不在唯一副本上试错。','Shade Smooth改变表面着色表现，不会自动把轮廓变圆。Bevel改变边缘几何。先判断目标游戏镜头能否看见差异，再决定是否增加面。'],
 initial='一件有授权的简单箱子或程序生成星星；白色中性光；固定近景和游戏距离两个机位。', controls='对象/几何演示切换、平滑开关、倒角0到0.06模型单位、近/远机位、法线示意。',
 steps=['用对象移动和移动全部顶点做A/B，观察原点及Transform。','只开平滑看轮廓；恢复后加小倒角看轮廓和高光。','切到游戏距离，选择保留的变化，填写尺寸与来源。'], feedback='把外轮廓、高光和原点分别标出；示意倒角不得只改亮度冒充几何。', failure='故障：模型尺寸靠极端缩放补偿，或者原点远离道具；先查来源尺度，再修静态资产。', reset='还原原始副本和固定机位；不覆盖源文件。',
 ui=['Blender：视口导航、Outliner选择、Object/Edit Mode、Item/Dimensions。','会定位：Bevel修改器、面朝向、Set Origin；Apply仅在理解静态对象影响后使用。','按需查：倒角全部选项、重拓扑、绑定对象的变换处理。'],
 questions=[('P','只用Shade Smooth能让箱子剪影变圆吗？','不能；它主要影响着色，不增加圆角几何。','只看外轮廓。'),('D','想把整件道具搬走却移了全部顶点，原点没跟走，你如何判断？','区分对象与几何操作，恢复后在正确模式移动。','看Transform和原点。'),('T','远处路灯不需要特写，是否仍要把每个螺丝建出来？','按镜头可见性和用途分配细节，不以面数衡量质量。','在游戏距离看。'),('K','拓扑需要现在完整学吗？','先知道连接结构影响变形和着色；遇到明确问题再查，不要求基础静态道具精通角色拓扑。','目标是静态还是变形？')], remember=['先修大形和尺度。','平滑不是倒角。','资产要有来源和源文件。'], recall=['A02','A03'], practice='后续可修改给定静态基底；当前课件不用另建Blender成品工程。', sources=['blender','gltf']),
 dict(id='B04', title='材质四个判断：颜色、粗糙、金属、共享', prereq=['B02','B03'], concepts='KN12/KN13/KN17', goal='在固定光照下调出两个不同材质，并只修改目标对象。',
 m=['用基础色、粗糙度、金属度做可解释的A/B。','区分自发光与照明，并检查共享材质的影响范围。'], k=['PBR/Normal Map是材质体系和表面细节手段；不学推导。'], stop='不推BRDF，不要求手绘复杂贴图，不把金属度当亮度旋钮。',
 body=['Base Color给基础颜色，Roughness控制反射粗糙程度，Metallic控制金属与非金属响应。看起来亮或暗还受灯光和环境影响，比较前要固定它们。','Emission让表面有发亮贡献，但光晕和照亮邻物需要相应渲染设置或光源。本课默认无GI/Glow。两个对象可以共用材质，改一处可能同时变；只改一个时要确认独立资源。'],
 initial='两个同尺寸球，共享同一材质；旁边灰箱；固定环境与机位，无GI/Glow。', controls='Roughness0.1到0.9、Metallic0/1、Emission0到3、独立光源开关、共享/独立切换。',
 steps=['预测粗糙度变化，拖动并比较高光而不是只看明暗。','将两个球分为独立材质，制作塑料与金属对照。','只调Emission观察灰箱，再单独开灯，解释两个结果。'], feedback='共享实验阶段，两球应随共享材质同步变化；进入材质A/B前先独立化，此时右球才固定为基线。显示共享标记与实际影响范围，不承诺网页PBR与Godot逐像素一致。', failure='故障：只想改左球却两个一起变；先确认材质共享，再最小分离，不复制整个项目。', reset='恢复材质、共享关系、灯光和相机；清空比较记录以外的运行状态。',
 ui=['Blender Principled BSDF/Godot StandardMaterial3D：基础色、粗糙度、金属度、自发光。','会定位：材质槽、Make Unique或等效独立化、灯光能量。','按需查：高级节点、GI/Glow开关和渲染器支持。'],
 questions=[('P','只提高Roughness一定等于变暗吗？','不一定；主要改变反射分布，明暗还取决于光照与环境。','固定灯光比较高光。'),('D','改一个球两个都变，先检查什么？','共享材质引用；按需求独立化，再核对其余对象未变化。','看资源而非复制场景次数。'),('T','做发亮蘑菇还要照亮地面，你如何拆需求？','表面Emission与实际照明分别测试；光晕又是另一项，不默认一项全包。','分别观察蘑菇和地面。'),('K','Normal Map主要有什么用？','改变表面着色方向表现细小凹凸，不自动改变轮廓或碰撞。','把视觉和几何分开。')], remember=['固定环境再比较材质。','Emission、光晕、照明分开验收。','调前确认共享范围。'], recall=['B02'], practice='后续在真实软件复现一次，不考节点图全部插槽。', sources=['pbr','resource']),
 dict(id='B05', title='资产往返：源文件改了，游戏别被改坏', prereq=['B04'], concepts='KN14/KN15', goal='画出静态资产的来源、导出、导入和包装关系，并排查一次重导入问题。',
 m=['区分源文件、交换文件、引擎导入数据和游戏包装场景。','修改静态资产后检查尺寸、材质与功能是否保留。'], k=['UV映射、glTF/GLB是按需理解的资源概念。'], stop='不背glTF JSON，不强制复杂UV展开，不处理绑定角色的变换烘焙。',
 body=['Blender源文件是制作依据，glTF/GLB用于交换；引擎生成的导入数据不应是唯一编辑来源。游戏的碰撞、脚本和交互最好与易被重导入的视觉资产分清。','Blender中复杂节点材质并非都能无损进入引擎。先用简单可交换材质验证，再决定烘焙贴图或在引擎重建。'],
 initial='四张可连线卡：source.blend、export.glb、imported visual、游戏包装；功能节点在包装层。', controls='修改源颜色/几何、模拟重导入、包装/导入层放置功能、查看变化清单。',
 steps=['先预测重新导入会替换哪部分；给四张卡排序。','修改源静态资产颜色并重导入，检查视觉更新和功能保留。','把脚本错误地放在易覆盖的生成层，观察模拟重导入的差异。'], feedback='明确这是流程模拟，不声称网页实际运行Blender导出。用前后清单显示保留/变化/丢失。', failure='故障：重导后碰撞不见了；检查编辑归属，而不是反复重新建碰撞却不留正确来源。', reset='还原四层关系和模拟资产版本；保存一次错误解释。',
 ui=['Blender：保存副本、选择导出；Godot：导入预览与包装场景。','会定位：Import面板、Reimport、导出Selected Objects。','按需查：具体导出扩展、动画选项、贴图烘焙。'],
 questions=[('P','只改引擎自动生成数据，下一次重导入一定保留吗？','不保证；应确认源数据和覆盖边界。','谁是来源？'),('D','Blender好看但GLB材质缺失，先怎么查？','核对导出支持的节点与贴图路径，做简单材质最小对照。','不要先加曝光补偿。'),('T','换外观模型后如何证明原拾取功能没损坏？','检查尺度与包装关系，做正确对象、计数、重开的回归，不能只看模型出现。','外观和功能分别验收。'),('K','GLB和UV各属于哪一类概念？','前者是交换容器/格式，后者是表面贴图坐标；不要求解析二进制。','哪个描述文件，哪个描述映射？')], remember=['源文件不能丢。','重导入会覆盖哪里要清楚。','Blender效果不自动等于引擎效果。'], recall=['B02','B04'], practice='真实静态资产往返在后续配套阶段执行；当前仅完成课堂规格与流程练习。', sources=['gltf','resource']),
 dict(id='B06', title='拾取只算一次：事件、条件与状态', prereq=['B05','A04'], concepts='KN16/KN06/KN07', goal='解释从进入检测区到计数变化的因果链，并抵抗重复触发。',
 m=['区分事件发生、条件过滤和状态归属。','验证正确对象只计一次，错误对象不计。'], k=['延迟释放表示对象不会在调用那一瞬间完全消失。'], stop='不做通用事件总线、背包、网络同步；只讲一条清晰事件链。',
 body=['事件告诉别人发生了什么；状态保存目前是什么。星星负责检测和防重复，关卡拥有总进度，UI读取它。看得见消失并不等于奖励处理正确。','先确认对象合法，再同步锁定已消耗状态，再通知计数。实际参考工程可能有两层防重；删掉一层未必马上重计。故障实验必须注明观察的是哪层，不能伪造结果。'],
 initial='玩家/装饰球二选一进入星星；事件日志、consumed和计数同屏；课堂只启用一层可见防重。', controls='进入按钮、同帧两次按钮、合法对象切换、consumed防重开关；教师可选双层对照。',
 steps=['先画检测→过滤→防重→通知→显示五张卡顺序。','测试错误对象、正确对象、同帧重复请求。','开启第二层防重，说明某一层关闭为什么仍可能不多加。'], feedback='每条日志显示接受或拒绝原因；计数来自状态，不从粒子或消失效果推断。', failure='故障：唯一防重被放在通知之后，导致重入重复；先给最小事件记录，学员恢复顺序。', reset='星星、计数、消耗标记和日志全复位，不只重画星星。',
 ui=['Godot：Area检测对象、信号连接、Inspector中的调试状态。','会定位：关卡计数拥有者、输出日志。','按需查：signal连接语法、queue_free生命周期细节。'],
 questions=[('P','同一星星触发两次，视觉只消失一次就能证明奖励没重复吗？','不能，要检查计数或奖励状态与事件日志。','证据在什么系统？'),('D','关闭对象防重却仍不重复，你能声称实验失败吗？','先查关卡是否还有防重；按实际系统层次解释，不编造重复。','可能还有哪个保护层？'),('T','把星星改成加能量的果实，应复用与改动哪些部分？','复用检测、合法对象过滤和一次性处理；改奖励状态与反馈，不直接乱改UI。','事件链和奖励类型分开。'),('K','延迟释放为什么值得认识？','同一轮事件仍可能看到对象或回调，所以防重不能只寄托删除。','不需要背引擎队列实现。')], remember=['事件不等于状态。','消失不等于只计一次。','先锁状态，再发通知。'], recall=['A04','A03'], practice='后续用引擎日志复核；Web事件模拟不是Godot生命周期证明。', sources=['area','resource']),
 dict(id='B07', title='反馈：让玩家知道刚才成功了', prereq=['B06'], concepts='KN18', goal='设计静音也能辨认的拾取反馈，不靠过亮和大粒子堆效果。',
 m=['把成功状态与视觉反馈明确对应。','比较反馈强度，检查不遮挡目标且静音可辨。'], k=['Tween、粒子、空间音效是可选表现工具。'], stop='不学整套音频工程和特效节点；不把华丽程度当评分依据。',
 body=['反馈服务于玩家识别：我碰到了吗、拿到了吗、还剩什么。稳定计数、短动效和声音可以互补；只有声音时静音玩家可能错过。','先做一项短反馈，再调持续时间和强度。持续闪烁、过强光晕或全屏效果可能遮住下一目标；偏好必须通过实际观察而不是口头说更刺激。'],
 initial='已有计数的拾取场景示意；一颗星；视觉提示持续0.3秒；声音默认关闭。', controls='提示开关、持续0.1到0.8秒、强度低/中/高、静音、减少动态效果。',
 steps=['先预测只靠声音时静音会漏掉什么。','保持计数不变，比较三档反馈强度，指出遮挡。','低动态模式下用稳定图标和文字继续表达成功。'], feedback='反馈必须由成功事件触发；失败接触不得播放成功效果。提供无音频替代而非自动播放声音。', failure='故障：错误对象碰星也显示成功；修触发条件，不能仅换颜色掩盖。', reset='清空短效果、恢复未拾取状态、保留用户静音设置。',
 ui=['Godot：动画时长、透明度/缩放等暴露参数、音量。','会定位：AnimationPlayer/Tween入口、Audio Bus。','按需查：粒子材质、空间衰减与混音技术。'],
 questions=[('P','计数没变但播放成功声，这算好反馈吗？','不算，反馈与状态冲突；要查成功事件。','以哪个状态为准？'),('D','粒子遮住下个目标，优先怎么改？','减强度或时长、改变范围并保持成功可辨，而不是继续加效果。','玩家接下来要看什么？'),('T','无声环境中如何保留拾取信息？','用稳定计数、短视觉或图标形成替代，不只换更响音效。','去掉声音仍能读懂吗？'),('K','Tween适合什么？','短时间内变化某个参数，如缩放或透明度；语法按需查。','不用列API。')], remember=['反馈要对应真实成功。','静音也能辨认。','少量清楚胜过大量遮挡。'], recall=['B06','B03'], practice='后续只实现一种反馈即可，不强制音效和粒子全做。', sources=['anim']),
 dict(id='B08', title='UI、完成和重开：状态只有一个来源', prereq=['B07'], concepts='KN16/KN18', goal='验证计数、完成和重开一致，并在窗口变化后仍可读。',
 m=['区分状态与显示，检查最后一次拾取和重开。','检查基本UI布局与信息层级。'], k=['Anchors/Containers是布局手段，具体选项用时查。'], stop='不做通用UI框架、复杂菜单系统或数据库。',
 body=['UI显示进度，不应成为另一个独立真相。关卡状态改变后通知显示；藏起计数不应让完成条件失效。','结尾边界比中间更容易暴露问题：零目标、一目标、最后一个、重开。小窗口也要能找到进度和重开，不要求学习全部Control节点。'],
 initial='任务总数3，状态0/3；显示计数、完成标记与重开按钮。', controls='合法拾取、重复事件、隐藏计数、重开、窗口宽1280/640、总数0/1/3。',
 steps=['先预测隐藏UI后是否还能完成。','按顺序拿到最后一个，重复触发，再重开两次。','缩窄窗口，查是否遮挡、裁切或不能操作。'], feedback='独立显示内部状态供教师核对，初始对学生隐藏；总数0采用明确约定而不算普遍引擎规则。', failure='故障：重开只重画星星，不清空计数；学员解释需要重置哪些状态。', reset='目标列表、计数、完成标记和UI一致；不能只改显示字符串。',
 ui=['Godot：Label文本、基本容器布局、运行窗口尺寸。','会定位：Control锚点、状态更新连接。','按需查：复杂响应式布局、完整UI主题系统。'],
 questions=[('P','隐藏计数Label应不应该停止计分？','不应该，显示不拥有玩法状态。','事件流是否仍在？'),('D','重开后一拿就完成，可能漏重置什么？','计数、已消费目标或完成状态；需按状态来源逐项核对。','只重画了什么？'),('T','总数变为1时你要补什么检查？','唯一目标就触发完成、重复不多加、重开归零；不能硬编码最后是第10个。','数量变了哪个边界变了？'),('K','容器布局解决什么？','帮助控件随尺寸组织位置；不要求记所有布局选项。','窗口变小会怎样？')], remember=['UI不是另一个计数器。','最后一个和重开一定测。','功能对了还要看得见。'], recall=['B06','B07'], practice='后续实际窗口检查是人工验收，不用假截图代替。', sources=['resource','anim']),
 dict(id='B09', title='柔和光照：先让目标被看见', prereq=['B08','B03'], concepts='KN13/KN25', goal='在同一机位做两版光照，说明哪版更符合温暖卡通目标。',
 m=['区分主光、环境与阴影，一次只调一项。','用主体可辨性而非越亮越好来验收。'], k=['曝光、色调映射、GI与烘焙解决不同问题。'], stop='不要求全部GI方案，不把Blender最终渲染等同于游戏效果。',
 body=['主光帮助读体积，环境影响暗部，阴影帮助读接触关系。全局提亮可能让背景和角色一起失去层次，不等于解决主体不清楚。','卡通或绘本可以有柔和暖色，但可玩目标仍须从背景中区分。用同机位同材质对照，才能知道光照修改带来的作用。'],
 initial='小屋、角色与星星；固定材质、相机和渲染模式；一盏方向光及环境填充。', controls='主光能量0.5到2、方向两档、环境弱/中、阴影开关；曝光作为观察项不强制操作。',
 steps=['先指出第一眼看到什么，再选一项目标：更柔和或更清晰。','只改光方向观察体积；恢复后只改环境观察暗部。','切到简化灰度对比，检查星星与背景是否仍区分。'], feedback='A/B同机位切换，记录光参数；灰度只是明暗检查手段，不自动判审美。', failure='故障：为照亮角色把所有灯都加亮，目标融入背景；要求局部与对比方案，不无脑加灯。', reset='恢复材质、灯光、环境与机位；保留选定风格目标。',
 ui=['Godot：DirectionalLight3D能量/方向、WorldEnvironment基本环境、阴影。','会定位：渲染器名称、曝光和色调映射。','按需查：GI类型、反射探针、烘焙参数。'],
 questions=[('P','提高所有灯亮度一定更易看见角色吗？','不一定；背景同步变亮可能破坏对比。','看相对关系。'),('D','改灯后不知道什么使画面更好，怎样重做实验？','恢复基线，同机位一次一变量，记录主体和背景变化。','把变量数量减下来。'),('T','温暖黄昏场景中黄色星星融入背景，怎样保留风格又能识别？','可改局部明暗、轮廓或周围背景，不必推翻整套暖色方案。','风格和功能怎样同时满足？'),('K','烘焙与实时光照为什么要区分？','动态变化支持和运行成本不同；此刻知道何时比较即可。','物体会不会动？')], remember=['先辨主体，再加气氛。','同机位做A/B。','发亮与照明分别验收。'], recall=['B04','B03'], practice='后续Godot中人工检查；网页模拟不承诺渲染器功能完全一致。', sources=['pbr','perf']),
 dict(id='B11', title='性能入门：先测，再判断要不要优化', prereq=['B09'], concepts='KN19/KN26', goal='读懂一组帧时间记录，用单变量对照提出一个合理判断。',
 m=['记录设备、分辨率、路线与帧时间，而非只报平均FPS。','比较开关同一效果的样本，区分证据与猜测。'], k=['Draw Call、VRAM、LOD和实例化是后续排查关键词。'], stop='不学GPU抓帧和流送实现，不要求自己写Profiler。',
 body=['60FPS对应约16.7毫秒一帧，但平均数会掩盖慢帧。性能比较必须在相同条件下进行，首次加载和稳定运行也要分开。','减少多边形并非解决所有慢帧。先定位现象，再做一项成本对照；如果已经满足目标，先停止优化，把精力留给体验。'],
 initial='教学用帧时间序列A=[12,13,12,35,12]、B=[11,12,12,14,12]；明确标合成数据，非真实硬件测试。', controls='逐帧查看、相同/不同分辨率标签、阴影开关两组数据、重复采样。',
 steps=['先找哪组有明显慢帧，再看平均值会漏掉什么。','将一组分辨率改低，判断能否再直接比较效果开关成本。','写下一次真实测试的设备、路线、预热和变量。'], feedback='图表数据来源始终可见；不虚构显卡性能，不因数字好看判通过。', failure='故障：同时降分辨率并关阴影，却声称全是阴影优化；要求控制变量重测。', reset='恢复相同条件与原样本，清空因果结论。',
 ui=['Godot：Debugger/Monitors或Profiler，分辨率与效果开关。','会定位：渲染器、性能日志、目标设备信息。','按需查：GPU工具、Draw Call统计细节和各优化API。'],
 questions=[('P','平均16毫秒但经常有40毫秒帧，是否一定流畅？','不能这样保证；需要看慢帧频率和场景。','平均数隐藏了什么？'),('D','同时改三个设置后更快，能确认哪个贡献最大吗？','不能；回到基线拆成单变量对照。','变量是否独立？'),('T','从桌面改到平板发布，哪些证据要重做？','目标设备、分辨率、输入和渲染条件下重新测，不直接搬桌面结论。','运行条件变了什么？'),('K','LOD的基本用途是什么？','按需要降低远处细节以节约成本，是否适合要测。','不要求实现算法。')], remember=['平均FPS不是全部体验。','先记条件再比较。','无瓶颈不要盲目优化。'], recall=['B09','A03'], practice='后续由真实引擎采样替换合成数据；课堂数据不得宣传为跑分。', sources=['perf']),
 dict(id='B12', title='验收AI改动：小假设、小修改、可回退', prereq=['B11'], concepts='KN20', goal='对一次有缺陷的AI修改提出最小修复与回归方案。',
 m=['给出复现步骤，限定一个待验证假设。','核对diff与需求，拒绝删除功能式修复。'], k=['自动测试、分支、日志是辅助工具，不是需要背的理论。'], stop='不背Git对象模型，不重构整个项目，不以代码行数评价完成。',
 body=['有效报错包含预期、实际、复现、版本和最近改动。先判断所属系统，再让AI提出可证伪的假设；一次改十个地方会让因果消失。','绿色测试也只证明测试覆盖的行为。AI如果删掉碰撞或关掉测试来消除报错，需求仍然失败。提交前核对改动范围和关键回归。'],
 initial='案例：换外观后玩家穿墙；三张修改卡分别是删碰撞、改错层、纯颜色；只一张引入故障。', controls='选择假设、查看diff、运行示意回归、回退单次修改；不用真实仓库权限。',
 steps=['写预期/实际/最短复现。','选择一个假设与一个测试，先预测结果再看日志。','检查AI修复是否改变原需求，列两个受影响功能回归。'], feedback='必须把修改卡与症状关联；没有提供日志时标待验证，不让AI声称运行成功。', failure='故障：AI让角色穿过所有墙从而不再卡住；需要恢复阻挡并定位真正卡住原因。', reset='退回已知正确版本；保存诊断记录但不保存个人账号或密钥。',
 ui=['编辑器：错误面板、输出、修改前后对照、回退。','会定位：Git提交历史、测试结果。','按需查：Git命令、高级调试器和重构模式。'],
 questions=[('P','不再报错是否等于需求完成？','不等于，要检验预期行为和改动副作用。','报错与功能是同一件事吗？'),('D','AI把失败测试删除后全绿，如何处理？','恢复有效测试，明确原需求，再做最小修复。','通过条件是否被偷偷改了？'),('T','材质突然影响整片森林，你先提供什么信息？','目标/实际、共享关系、最近修改、最小复现和固定机位对照。','先定位系统。'),('K','版本回退的用途是什么？','恢复已知正确状态并比较变化，不是一定要学Git内部存储。','基线有什么价值？')], remember=['报错消失不等于功能正确。','一次验证一个假设。','AI没运行就不能说通过。'], recall=['A03','B04','B06'], practice='后续让学员亲自检查一次真实diff；不提供账户操作或强制push教程。', sources=['perf','resource']),
 dict(id='B13', title='初级结业：把星星换成另一种可用物品', prereq=['B12'], concepts='KN05/KN06/KN07/KN12/KN16/KN18/KN20', goal='用已学知识完成一种新拾取物，并证明关键条件没有被破坏。',
 m=['迁移外观、检测、一次性状态和反馈。','对AI修改做功能回归并解释结果。'], k=['只抽本阶段已经介绍的用途词，不增加新术语。'], stop='不突然加入敌人、背包、绑定、多人；不要求做完整跨阶段题库。',
 body=['迁移不是逐步抄原星星：新道具可能更小、颜色更接近背景，检测与反馈要随用途核对。实现可以由AI完成，选择、预测和验收由学员承担。','提交最少证据：需求一句、改动范围、一次正常测试、一次关键异常、一个次日变式。不会某项就补对应实验，不重看全部课程。'],
 initial='可选果实/能量球两张需求卡，已存在检测和计数流程；不预先给目标参数。', controls='选择外观尺寸、材质、检测范围和反馈；测试正确/错误对象、重复/重开。',
 steps=['先写新物品与星星有哪些相同、不同时。','限定AI只改必要对象，学员自己选参数并测试。','抽一个未见故障，然后换另一种大小或颜色复测。'], feedback='按功能证据判定，不按美术复杂度或代码数量。缺证据时标待验证。', failure='随机一个故障：Mask、共享材质或未重置；不得同时塞三个让学员猜。', reset='恢复原星星版本，保留新方案为独立练习副本。',
 ui=['复用初级已学的Inspector、场景树、材质和检测参数。','会定位：日志与版本差异。','按需查：语法、菜单路径，不增加新工具。'],
 questions=[('P','只换颜色就一定成为合格新拾取物吗？','不一定；还要核对目标识别、状态、检测和反馈。','需求是否只包含颜色？'),('D','重开后新物品不出现，怎样缩小问题？','比较状态重置、生成和视觉显示，按一次一个假设验证。','先找哪一步失败。'),('T','换成更小果实但保持容易拾取，怎样取舍？','外观尺寸和检测范围分别设计，确保反馈与位置可信并实际测试。','视觉与检测可以不同但要合理。'),('K','本阶段哪些实现可以交AI？','样板脚本、查API、准备测试；需求、判断和证据解释由人负责。','分清实现与验收。')], remember=['换对象仍会用才算迁移。','只补失败的关键能力。','代码可外包，验收不能。'], recall=['A04','B04','B06','B12'], practice='完整游戏工程的实操验收稍后开展；此处是结业课堂与评价设计，不宣称已有学习者通过。', sources=['area','resource','perf'])
]
